<script setup lang="ts">
const [{data:settingsResponse},{data:postsResponse},{data:projectsResponse}]=await Promise.all([useFetch<any>('/api/settings'),useFetch<any>('/api/posts',{query:{pageSize:4}}),useFetch<any>('/api/projects')]);const settings=computed(()=>settingsResponse.value.data);const posts=computed(()=>postsResponse.value.data.items);const projects=computed(()=>projectsResponse.value.data.slice(0,settings.value.featuredProjectCount));const techIcons:Record<string,string>={nuxt:'i-logos-nuxt-icon',nuxtjs:'i-logos-nuxt-icon','nuxt.js':'i-logos-nuxt-icon',typescript:'i-logos-typescript-icon',postgres:'i-logos-postgresql',postgresql:'i-logos-postgresql'};const techIcon=(name:string)=>techIcons[name.trim().toLowerCase()]||'i-lucide-code-2';const socialPlatforms=[{key:'github',label:'GitHub',icon:'i-simple-icons-github',color:'var(--color-text)'},{key:'twitter',label:'Twitter',icon:'i-simple-icons-twitter',color:'#1d9bf0'},{key:'linkedin',label:'LinkedIn',icon:'i-simple-icons-linkedin',color:'#0a66c2'},{key:'juejin',label:'掘金',icon:'i-simple-icons-juejin',color:'#1e80ff'},{key:'zhihu',label:'知乎',icon:'i-simple-icons-zhihu',color:'#056de8'},{key:'xiaohongshu',label:'小红书',icon:'i-simple-icons-xiaohongshu',color:'#ff2442'}] as const;const socialLinks=computed(()=>socialPlatforms.map(item=>({...item,href:settings.value.social?.[item.key]})).filter(item=>item.href));useSeoMeta({title:()=>settings.value.seo.title||settings.value.siteName,description:()=>settings.value.seo.description||settings.value.siteDescription,ogImage:()=>settings.value.seo.ogImage||undefined})
</script>
<template><div class="home"><section class="hero"><img class="hero-avatar" :src="settings.avatarUrl||'/favicon.png'" :alt="`${settings.personName} 的头像`"><p class="eyebrow">{{settings.currentStatus}}</p><h1>你好，我是 {{settings.personName}}。</h1><p class="lead">{{settings.bio}}</p><div class="tech"><span v-for="item in settings.techStack" :key="item"><UIcon class="tech-icon" :name="techIcon(item)" aria-hidden="true" />{{item}}</span></div><nav v-if="socialLinks.length" class="social-links" aria-label="社交链接"><a v-for="item in socialLinks" :key="item.key" class="social-link" :href="item.href" target="_blank" rel="noopener noreferrer" :aria-label="item.label" :title="item.label" :style="{color:item.color}"><UIcon class="social-link-icon" :name="item.icon" aria-hidden="true" /></a></nav></section><section><div class="section-head"><h2>最近文章</h2><NuxtLink to="/blog">查看全部 →</NuxtLink></div><div class="recent"><NuxtLink v-for="post in posts" :key="post.id" :to="`/blog/${post.id}`"><div><strong>{{post.title}}</strong><p>{{post.summary}}</p></div><time>{{new Date(post.publishedAt).toLocaleDateString('zh-CN')}}</time></NuxtLink></div></section><section v-if="projects.length"><div class="section-head"><h2>精选项目</h2><NuxtLink to="/projects">查看全部 →</NuxtLink></div><div class="home-projects"><a v-for="p in projects" :key="p.id" :href="p.websiteUrl||p.githubUrl" target="_blank" rel="noopener noreferrer"><strong>{{p.name}}</strong><p>{{p.summary}}</p></a></div></section></div></template>
<style scoped>.home{display:grid;gap:54px}.hero-avatar{display:block;width:48px;height:48px;margin-bottom:18px;border:1px solid var(--color-border);border-radius:50%;background:var(--color-background-secondary);object-fit:cover;object-position:center;box-shadow:0 4px 14px rgba(0,0,0,.08)}.hero h1{font-size:30px}.tech{display:flex;flex-wrap:wrap;gap:8px;margin-top:22px}.tech span{display:inline-flex;align-items:center;gap:6px;padding:5px 9px;border:1px solid var(--color-border);border-radius:99px;color:var(--color-text-secondary);font-size:11px}.tech-icon{width:13px;height:13px;flex:0 0 auto}.social-links{display:flex;flex-wrap:wrap;gap:9px;margin-top:18px}.social-link{display:grid;width:34px;height:34px;place-items:center;border:1px solid var(--color-border);border-radius:50%;background:var(--color-background);transition:transform .16s ease,border-color .16s ease,background .16s ease}.social-link:hover{transform:translateY(-2px);border-color:currentColor;background:color-mix(in srgb,currentColor 8%,transparent)}.social-link-icon{width:15px;height:15px}.section-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}.section-head h2{margin:0;font-size:16px}.section-head a{color:var(--color-primary);font-size:11px}.recent{display:grid}.recent>a{display:flex;justify-content:space-between;gap:20px;padding:17px 0;border-bottom:1px solid var(--color-border)}.recent strong,.home-projects strong{font-size:14px}.recent p,.home-projects p{margin:6px 0 0;color:var(--color-text-secondary);font-size:12px;line-height:1.6}.recent time{white-space:nowrap;color:var(--color-text-secondary);font-size:10px}.home-projects{display:grid;grid-template-columns:1fr 1fr;gap:12px}.home-projects a{padding:17px;border:1px solid var(--color-border);border-radius:var(--radius-md)}@media(max-width:600px){.home-projects{grid-template-columns:1fr}}</style>
